+            loading = false;
+        }
+    }
+
+    private List<TaskItem> GetFilteredTasks(string status)
+    {
+        var tasks = allTasks.Where(t => t.Status == status);
+        if (!string.IsNullOrWhiteSpace(searchText))
+            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
+        return tasks.ToList();
+    }
+
+    private async Task MoveTask(int taskId, string currentStatus, int direction)
+    {
+        var currentIndex = Array.IndexOf(columns, currentStatus);
+        var newIndex = currentIndex + direction;
+        if (newIndex < 0 || newIndex >= columns.Length) return;
+
+        var newStatus = columns[newIndex];
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = allTasks.First(t => t.Id == taskId);
+            allTasks[allTasks.IndexOf(task)] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async Task AddTask(AddTaskForm.AddTaskRequest req, string status)
+    {
+        try
+        {
+            var newTask = await TaskService.CreateTaskAsync(req.Title, req.Assignee, req.Priority, req.DueDate);
+            // Service creates with default status; ensure it matches the column
+            allTasks.Add(newTask with { Status = status });
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
